1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { registrarConfigured, transfersAvailable, getDnsHosts } from "@/lib/registrar";
5	import { StatCard, Badge, StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
6	import { PortalHero } from "@/components/portal/PortalHero";
7	import { DomainSearch } from "@/components/customer/DomainSearch";
8	import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";
9	
10	export const dynamic = "force-dynamic";
11	
12	function daysUntil(d: Date): number {
13	  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
14	}
15	
16	function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
17	  if (days === null) return "slate";
18	  if (days < 0) return "red";
19	  if (days <= 30) return "amber";
20	  return "green";
21	}
22	
23	function expiryLabel(d: Date | null): string {
24	  if (!d) return "—";
25	  const days = daysUntil(d);
26	  if (days < 0) return `expired ${-days}d ago`;
27	  if (days === 0) return "expires today";
28	  return `in ${days} day${days === 1 ? "" : "s"}`;
29	}
30	
31	const statusDotFor = (s: string) =>
32	  s === "ACTIVE"
33	    ? "RUNNING"
34	    : s === "PENDING" || s === "TRANSFER_PENDING"
35	      ? "PENDING"
36	      : s === "EXPIRED"
37	        ? "SUSPENDED"
38	        : "ERROR";
39	
40	export default async function DomainsPage() {
41	  const user = await requireUser();
42	  const configured = registrarConfigured();
43	  const canTransfer = transfersAvailable();
44	  const domains = await db.domain.findMany({
45	    where: { userId: user.id },
46	    orderBy: { createdAt: "desc" },
47	  });
48	
49	  // DNS record counts for active domains (best-effort — registrar may be briefly unavailable).
50	  const recordCounts = new Map<string, number | null>();
51	  if (configured) {
52	    await Promise.all(
53	      domains
54	        .filter((d) => d.status === "ACTIVE")
55	        .map(async (d) => {
56	          try {
57	            const hosts = await getDnsHosts(d.name);
58	            recordCounts.set(d.id, hosts.length);
59	          } catch {
60	            recordCounts.set(d.id, null);
61	          }
62	        })
63	    );
64	  }
65	
66	  const active = domains.filter((d) => d.status === "ACTIVE").length;
67	  const expiringSoon = domains.filter(
68	    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
69	  ).length;
70	
71	  return (
72	    <div className="space-y-6">
73	      <PortalHero variant="domains" title="Domains" sub="Register, transfer in and manage domains, right next to your servers.">
74	        {canTransfer && (
75	          <Link href="/dashboard/domains/transfer" className="btn-secondary">
76	            Transfer a domain in
77	          </Link>
78	        )}
79	        {configured && (
80	          <Link href="/dashboard/domains/ideas" className="btn-secondary">
81	            Find a name
82	          </Link>
83	        )}
84	        {configured && (
85	          <Link href="/dashboard/domains/register" className="btn-primary">
86	            Register a domain
87	          </Link>
88	        )}
89	      </PortalHero>
90	
91	      <DomainSearch configured={configured} />
92	
93	      {domains.length > 0 && (
94	        <div className="grid gap-4 sm:grid-cols-3">
95	          <StatCard
96	            label="Domains"
97	            value={String(domains.length)}
98	            icon={
99	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
100	                <circle cx="12" cy="12" r="9" />
101	                <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
102	              </svg>
103	            }
104	          />
105	          <StatCard
106	            label="Active"
107	            value={String(active)}
108	            delta={active === domains.length ? "all active" : `${domains.length - active} inactive`}
109	            deltaGood={active === domains.length}
110	          />
111	          <StatCard
112	            label="Expiring soon"
113	            value={String(expiringSoon)}
114	            delta={expiringSoon === 0 ? "nothing due" : "within 30 days"}
115	            deltaGood={expiringSoon === 0}
116	          />
117	        </div>
118	      )}
119	
120	      {domains.length === 0 ? (
121	        <EmptyState
122	          title="No domains yet"
123	          sub={
124	            configured
125	              ? "Search above for an exact name, or let the generator turn a description of your business into available ones — then register and point it at any of your servers in minutes."
126	              : "Domain registration lights up once the registrar integration is configured. Your registered domains will appear here."
127	          }
128	          action={
129	            configured || canTransfer ? (
130	              <div className="flex flex-wrap items-center justify-center gap-3">
131	                {configured && (
132	                  <Link href="/dashboard/domains/register" className="btn-primary">
133	                    Register your first domain
134	                  </Link>
135	                )}
136	                {configured && (
137	                  <Link href="/dashboard/domains/ideas" className="btn-secondary">
138	                    Not sure what to call it? Generate names
139	                  </Link>
140	                )}
141	                {canTransfer && (
142	                  <Link href="/dashboard/domains/transfer" className="btn-secondary">
143	                    Already own one? Transfer it in
144	                  </Link>
145	                )}
146	              </div>
147	            ) : undefined
148	          }
149	        />
150	      ) : (
151	        <div className="card p-0">
152	          <div className="flex items-center justify-between px-5 pt-5">
153	            <p className="section-label">Your domains</p>
154	            <span className="text-xs text-slate-500">{domains.length} total</span>
155	          </div>
156	
157	          {/* Card grid on small screens, table on large */}
158	          <div className="grid gap-3 p-5 lg:hidden">
159	            {domains.map((d) => {
160	              const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
161	              const count = recordCounts.get(d.id);
162	              return (
163	                <Link
164	                  key={d.id}
165	                  href={`/dashboard/domains/${d.id}`}
166	                  className="card card-hover block p-4"
167	                >
168	                  <div className="flex items-center justify-between gap-2">
169	                    {/* min-w-0 so `truncate` can actually shrink a long domain
170	                        name at 390px instead of pushing the status dot off-card. */}
171	                    <span className="min-w-0 truncate font-mono text-sm font-semibold text-slate-100">{d.name}</span>
172	                    <StatusDot status={statusDotFor(d.status)} label={d.status} />
173	                  </div>
174	                  {d.status === "TRANSFER_PENDING" && (
175	                    <p className="mt-2 text-xs text-amber-300">
176	                      Transfer in progress — approve the confirmation email from your old registrar. Usually
177	                      5–7 days.
178	                    </p>
179	                  )}
180	                  {d.status === "TRANSFER_FAILED" && (
181	                    <p className="mt-2 text-xs text-red-300">
182	                      Transfer didn&apos;t complete — you were credited back. Tap to see why.
183	                    </p>
184	                  )}
185	                  <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
186	                    {d.status === "TRANSFER_PENDING" ? (
187	                      <Badge tone="amber">transfer in</Badge>
188	                    ) : (
189	                      <Badge tone={expiryTone(days)}>{expiryLabel(d.expiresAt)}</Badge>
190	                    )}
191	                    <Badge tone={d.autoRenew ? "green" : "slate"}>
192	                      auto-renew {d.autoRenew ? "on" : "off"}
193	                    </Badge>
194	                    {d.status === "ACTIVE" && (
195	                      <Badge tone="slate">{count === null || count === undefined ? "DNS —" : `${count} DNS`}</Badge>
196	                    )}
197	                    <span className="ml-auto text-slate-400">{fmtMoney(d.priceCents)}/yr</span>
198	                  </div>
199	                </Link>
200	              );
201	            })}
202	          </div>
203	
204	          <div className="hidden overflow-x-auto lg:block">
205	            <table className="table-shell mt-2 min-w-[760px]">
206	              <thead>
207	                <tr>
208	                  <th>Domain</th>
209	                  <th>Status</th>
210	                  <th>Expires</th>
211	                  <th>DNS</th>
212	                  <th>Price</th>
213	                  <th>Auto-renew</th>
214	                  <th className="text-right">Actions</th>
215	                </tr>
216	              </thead>
217	              <tbody>
218	                {domains.map((d) => {
219	                  const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
220	                  const count = recordCounts.get(d.id);
221	                  return (
222	                    <tr key={d.id}>
223	                      <td>
224	                        <Link
225	                          href={`/dashboard/domains/${d.id}`}
226	                          className="font-mono text-sm font-semibold text-slate-100 hover:text-brand-300"
227	                        >
228	                          {d.name}
229	                        </Link>
230	                      </td>
231	                      <td>
232	                        <StatusDot status={statusDotFor(d.status)} label={d.status} />
233	                      </td>
234	                      <td>
235	                        {d.status === "TRANSFER_PENDING" ? (
236	                          <div className="flex flex-col">
237	                            <span className="text-sm text-amber-300">transferring in</span>
238	                            <span className="text-xs text-slate-500">approve the registrar email · 5–7 days</span>
239	                          </div>
240	                        ) : d.expiresAt ? (
241	                          <div className="flex flex-col">
242	                            <span className="text-sm text-slate-300">
243	                              {d.expiresAt.toISOString().slice(0, 10)}
244	                            </span>
245	                            <span className={`text-xs ${expiryTone(days) === "amber" ? "text-amber-400" : expiryTone(days) === "red" ? "text-red-400" : "text-slate-500"}`}>
246	                              {expiryLabel(d.expiresAt)}
247	                            </span>
248	                          </div>
249	                        ) : (
250	                          <span className="text-slate-500">—</span>
251	                        )}
252	                      </td>
253	                      <td className="text-slate-400">
254	                        {d.status !== "ACTIVE"
255	                          ? "—"
256	                          : count === null || count === undefined
257	                            ? "—"
258	                            : `${count} record${count === 1 ? "" : "s"}`}
259	                      </td>
260	                      <td className="text-slate-400">{fmtMoney(d.priceCents)}/yr</td>
261	                      <td>
262	                        <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} />
263	                      </td>
264	                      <td className="text-right">
265	                        <Link href={`/dashboard/domains/${d.id}`} className="btn-secondary px-3 py-1 text-xs">
266	                          Manage
267	                        </Link>
268	                      </td>
269	                    </tr>
270	                  );
271	                })}
272	              </tbody>
273	            </table>
274	          </div>
275	        </div>
276	      )}
277	    </div>
278	  );
279	}
