1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser, assertNotImpersonating } from "./auth";
8	import {
9	  registrarConfigured,
10	  checkDomains,
11	  registerDomain,
12	  renewDomain,
13	  domainInfo,
14	  listRecords,
15	  addRecord,
16	  deleteRecord,
17	  type RegistrantContact,
18	} from "./registrar";
19	import { domainTerm, domainTermPriceCents } from "./billing-terms";
20	import { debitWallet, InsufficientBalanceError } from "./wallet";
21	import { getSettingBool } from "./settings";
22	import { emailVerificationError } from "./email-verification";
23	import { cookies } from "next/headers";
24	import { partnerSourceFromCookie, notifyPartner } from "./partner";
25	
26	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
27	
28	/* ------------------------------------------------------------------ *
29	 * Idempotency helpers
30	 *
31	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
32	 * user+domain. Catches the double-click / impatient-retry case immediately and
33	 * keeps two concurrent requests from both reaching the registrar. Best-effort
34	 * only — it does not survive a restart or span multiple app instances.
35	 *
36	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
37	 * charge+create runs in one `$transaction`, so a duplicate can never both take
38	 * money and create a second row. Renewal is guarded by an in-transaction expiry
39	 * re-check (charge and expiry advance together atomically).
40	 * ------------------------------------------------------------------ */
41	
42	const SUBMIT_GUARD_MS = 120_000;
43	const inFlightSubmits = new Map<string, number>();
44	
45	function beginSubmit(key: string): boolean {
46	  const now = Date.now();
47	  const heldUntil = inFlightSubmits.get(key);
48	  if (heldUntil !== undefined && heldUntil > now) return false;
49	  if (inFlightSubmits.size > 2000) {
50	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
51	  }
52	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
53	  return true;
54	}
55	
56	function endSubmit(key: string): void {
57	  inFlightSubmits.delete(key);
58	}
59	
60	class DuplicateDomainError extends Error {
61	  constructor() {
62	    super("DUPLICATE_DOMAIN");
63	    this.name = "DuplicateDomainError";
64	  }
65	}
66	
67	const isUniqueConflict = (e: any) => e?.code === "P2002";
68	
69	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
70	
71	/**
72	 * After a registrar call fails or times out we must NOT assume the registration
73	 * did not happen — name.com may well have taken the order. Ask the registrar
74	 * before touching the customer's money:
75	 *  - the domain is in our reseller account  -> registered (keep the charge)
76	 *  - the domain is still purchasable        -> not registered (safe to refund)
77	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
78	 */
79	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
80	  try {
81	    const info = await domainInfo(domain);
82	    return { state: "registered", expires: info.expires };
83	  } catch {
84	    /* not in our account, or the API is unhappy — fall through to availability */
85	  }
86	  try {
87	    const [check] = await checkDomains([domain]);
88	    if (check?.available === true) return { state: "not-registered" };
89	  } catch {
90	    /* registrar unreachable */
91	  }
92	  return { state: "unknown" };
93	}
94	
95	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
96	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
97	  // asset from a registrar in the customer's name, with registrant contact details
98	  // taken from this form. `submitTransferIn` — the same product, the same money —
99	  // has carried this guard since it was written; registration and renewal never did.
100	  await assertNotImpersonating();
101	  const user = await requireUser();
102	  // Purchase gate: an unverified address means we cannot reach the person we
103	  // are about to charge. See lib/email-verification.ts.
104	  const unverified = await emailVerificationError(user);
105	  if (unverified) return { error: unverified };
106	  // Feature flag: domain registration can be switched off platform-wide.
107	  if (!(await getSettingBool("feature_domains", true))) {
108	    return { error: "Domain registration is currently unavailable." };
109	  }
110	  if (!registrarConfigured()) {
111	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
112	  }
113	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
114	  // /dashboard/domains, captured into a cookie by PartnerSourceCapture). Read
115	  // synchronously here (unlike the VPS path, domain purchase is a same-request
116	  // wallet debit — no Stripe checkout/webhook race to round-trip through).
117	  const partnerSource = partnerSourceFromCookie(await cookies());
118	  const contactSchema = z.object({
119	    firstName: z.string().min(1).max(60),
120	    lastName: z.string().min(1).max(60),
121	    address1: z.string().min(1).max(120),
122	    city: z.string().min(1).max(60),
123	    stateProvince: z.string().min(1).max(60),
124	    postalCode: z.string().min(1).max(20),
125	    country: z.string().length(2),
126	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
127	    email: z.string().email(),
128	  });
129	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
130	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
131	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
132	
133	  const contactParsed = contactSchema.safeParse({
134	    firstName: formData.get("firstName"),
135	    lastName: formData.get("lastName"),
136	    address1: formData.get("address1"),
137	    city: formData.get("city"),
138	    stateProvince: formData.get("stateProvince"),
139	    postalCode: formData.get("postalCode"),
140	    country: String(formData.get("country") ?? "").toUpperCase(),
141	    phone: formData.get("phone"),
142	    email: formData.get("email"),
143	  });
144	  if (!contactParsed.success) {
145	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
146	  }
147	
148	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
149	  const guardKey = `register:${user.id}:${domain}`;
150	  if (!beginSubmit(guardKey)) {
151	    return { error: "That registration is already being processed — give it a moment before retrying." };
152	  }
153	
154	  try {
155	    const existing = await db.domain.findUnique({ where: { name: domain } });
156	    if (existing) {
157	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
158	      if (existing.status === "PENDING") {
159	        return { error: "You already have a registration in progress for this domain." };
160	      }
161	      return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
162	    }
163	
164	    // Live availability + retail(markup) & cost prices from name.com
165	    let priceCents: number; // retail per year (customer)
166	    let costCents: number; // registrar cost per year (us)
167	    try {
168	      const [check] = await checkDomains([domain]);
169	      if (!check) return { error: "Could not check availability. Try again." };
170	      if (!check.available) return { error: "Domain is not available." };
171	      if (check.premium) return { error: "Premium domains are not supported yet." };
172	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
173	      priceCents = check.priceCents;
174	      costCents = check.costCents;
175	    } catch (e: any) {
176	      return { error: String(e?.message ?? e).slice(0, 200) };
177	    }
178	
179	    const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
180	    const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
181	    if (user.balanceCents < totalCents) {
182	      return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
183	    }
184	
185	    let record;
186	    try {
187	      record = await db.$transaction(async (tx) => {
188	        // Re-check inside the transaction: the availability round-trip above is
189	        // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
190	        // even if this read misses, the create below rolls the whole debit back.
191	        const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
192	        if (dupe) throw new DuplicateDomainError();
193	        await debitWallet(tx, user.id, totalCents);
194	        await tx.walletTransaction.create({
195	          data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
196	        });
197	        return tx.domain.create({
198	          data: {
199	            name: domain,
200	            userId: user.id,
201	            priceCents,
202	            costCents,
203	            termYears: dTerm.years,
204	            status: "PENDING",
205	            registrar: "name.com",
206	            partnerSource: partnerSource ?? null,
207	          },
208	        });
209	      });
210	    } catch (e) {
211	      if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
212	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
213	        return { error: "This domain is already being registered — you have not been charged twice." };
214	      }
215	      throw e;
216	    }
217	
218	    try {
219	      const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
220	      const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
221	      await db.domain.update({
222	        where: { id: record.id },
223	        data: {
224	          status: "ACTIVE",
225	          registeredAt: new Date(),
226	          expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
227	        },
228	      });
229	      await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
230	      await db.notification.create({
231	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
232	      });
233	      // Tell the partner (best-effort, never blocks the order) — only for orders
234	      // tagged via a partner deep link. Most domain registrations are direct Nxeon
235	      // customers and must never be forwarded to a partner's webhook.
236	      if (partnerSource === "kodely") {
237	        await notifyPartner("domain.registered", { userId: user.id, domain, expiresAt: info.expires ?? null });
238	      }
239	    } catch (e: any) {
240	      const reason = String(e?.message ?? e).slice(0, 400);
241	      // NEVER refund blind: a timeout/5xx often means the order DID go through.
242	      const verdict = await verifyRegistration(domain);
243	
244	      if (verdict.state === "registered") {
245	        // The registration exists — keep the charge and finish the record.
246	        await db.domain.update({
247	          where: { id: record.id },
248	          data: {
249	            status: "ACTIVE",
250	            registeredAt: new Date(),
251	            expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
252	            error: `Recovered after registrar error: ${reason}`.slice(0, 500),
253	          },
254	        });
255	        await db.auditLog.create({
256	          data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
257	        });
258	        await db.notification.create({
259	          data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
260	        });
261	        // `?new=1` triggers the one-time "domain registered" success banner +
262	        // hosting/VPS upsell on the domain page (app/dashboard/domains/[id]/page.tsx).
263	        redirect(`/dashboard/domains/${record.id}?new=1`);
264	      }
265	
266	      if (verdict.state === "not-registered") {
267	        // Confirmed still available at the registrar — refunding is safe.
268	        await db.$transaction([
269	          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
270	          db.walletTransaction.create({
271	            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
272	          }),
273	          db.domain.update({
274	            where: { id: record.id },
275	            data: { status: "FAILED", error: reason.slice(0, 500) },
276	          }),
277	        ]);
278	        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
279	      }
280	
281	      // Unknown: leave PENDING and charged, flag for manual review. Refunding
282	      // here risks giving away a domain we actually paid the registrar for.
283	      await db.domain.update({
284	        where: { id: record.id },
285	        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
286	      });
287	      await db.auditLog.create({
288	        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
289	      });
290	      await db.notification.create({
291	        data: {
292	          userId: user.id,
293	          title: `Domain ${domain} needs review`,
294	          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
295	          href: `/dashboard/domains/${record.id}`,
296	        },
297	      });
298	      return {
299	        error:
300	          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
301	          `It is marked for review — do not retry, you will not be charged twice.`,
302	      };
303	    }
304	    redirect(`/dashboard/domains/${record.id}?new=1`);
305	  } finally {
306	    endSubmit(guardKey);
307	  }
