310	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
311	const RENEW_SLACK_MS = 30 * 86400_000;
312	
313	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
314	  // Spend path: a manual renewal debits the wallet and spends at the registrar.
315	  // See purchaseDomain above.
316	  await assertNotImpersonating();
317	  const user = await requireUser();
318	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
319	  // renewal runs in the worker and does not come through here, so no existing
320	  // domain can lapse because of this check.
321	  const unverifiedRenew = await emailVerificationError(user);
322	  if (unverifiedRenew) return { error: unverifiedRenew };
323	  const domain = await db.domain.findUnique({ where: { id: domainId } });
324	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
325	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
326	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
327	
328	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
329	  const guardKey = `renew:${domain.userId}:${domain.name}`;
330	  if (!beginSubmit(guardKey)) {
331	    return { error: "A renewal for this domain is already in progress." };
332	  }
333	
334	  try {
335	    const dTerm = domainTerm(domain.termYears);
336	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
337	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
338	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
339	
340	    const dbExpiry = domain.expiresAt ?? null;
341	
342	    // Idempotency: charge and expiry advance together in one transaction below,
343	    // so if the registrar expiry is already ahead of ours a previous attempt
344	    // renewed but never got charged/recorded. Adopt that renewal instead of
345	    // buying a second year.
346	    let registrarExpiry: Date | undefined;
347	    try {
348	      registrarExpiry = (await domainInfo(domain.name)).expires;
349	    } catch {
350	      /* non-fatal: fall through to a normal renew */
351	    }
352	    const alreadyRenewed =
353	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
354	
355	    if (!alreadyRenewed) {
356	      try {
357	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
358	      } catch (e: any) {
359	        // The registrar call is the FIRST thing that happens, before any debit,
360	        // so "you have not been charged" is a fact here, not a hope — and saying
361	        // it stops a customer retrying a renewal they think half-succeeded.
362	        return {
363	          error:
364	            `The registrar refused to renew ${domain.name}: ${String(e?.message ?? e).slice(0, 200)}. ` +
365	            `Nothing has been charged. Wait a few minutes and try again; if it keeps failing, contact support with this message.`,
366	        };
367	      }
368	      registrarExpiry = await domainInfo(domain.name)
369	        .then((i) => i.expires)
370	        .catch(() => undefined);
371	    }
372	
373	    const targetExpiry =
374	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
375	
376	    try {
377	      const charged = await db.$transaction(async (tx) => {
378	        // Re-read under the transaction: if a concurrent request already advanced
379	        // the expiry it also already took the money — do not charge again.
380	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
381	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
382	          return false;
383	        }
384	        await debitWallet(tx, domain.userId, renewCents);
385	        await tx.walletTransaction.create({
386	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
387	        });
388	        await tx.domain.update({
389	          where: { id: domainId },
390	          data: { expiresAt: targetExpiry, status: "ACTIVE" },
391	        });
392	        return true;
393	      });
394	      if (!charged) {
395	        revalidatePath(`/dashboard/domains/${domainId}`);
396	        return {};
397	      }
398	    } catch (e) {
399	      if (e instanceof InsufficientBalanceError) {
400	        // The registrar renewal already succeeded — flag the uncollected charge
401	        // instead of silently swallowing it.
402	        await db.auditLog
403	          .create({
404	            data: {
405	              userId: domain.userId,
406	              action: "domain.renew.uncharged",
407	              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
408	            },
409	          })
410	          .catch(() => {});
411	        return { error: "Insufficient balance." };
412	      }
413	      throw e;
414	    }
415	    revalidatePath(`/dashboard/domains/${domainId}`);
416	    return {};
417	  } finally {
418	    endSubmit(guardKey);
419	  }
420	}
