519	/**
520	 * One-click: point apex + www at the platform's public IP.
521	 *
522	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
523	 * only then add the replacements — so a registrar hiccup, a rate limit or a
524	 * network blip in between took the domain DARK and left it that way, with an
525	 * error message that did not say the old records were already gone. That is the
526	 * "six domains dark while the run scored 4/4" failure shape: destructive work
527	 * done first, on the assumption the constructive half cannot fail.
528	 *
529	 * The new order is also idempotent — an A record already pointing at `ip` is
530	 * kept rather than churned — so clicking twice is free, and a half-finished run
531	 * can simply be retried.
532	 */
533	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
534	  let ctx;
535	  try {
536	    ctx = await ownedDomain(domainId);
537	  } catch (e: any) {
538	    return { error: e.message };
539	  }
540	  const ip = process.env.PUBLIC_IP;
541	  if (!ip) {
542	    return {
543	      error:
544	        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
545	        "Contact support — this is a platform configuration problem, not something you can fix from here.",
546	    };
547	  }
548	
549	  const done: string[] = [];
550	  try {
551	    const recs = await listRecords(ctx.domain.name);
552	    for (const host of ["", "www"]) {
553	      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
554	      const existing = recs.filter((r) => r.host === host && r.type === "A");
555	      const keep = existing.find((r) => r.answer === ip);
556	      // Constructive half FIRST: the name resolves somewhere at every instant.
557	      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
558	      // Only now retire the records that point elsewhere.
559	      for (const r of existing) {
560	        if (keep && r.id === keep.id) continue;
561	        await deleteRecord(ctx.domain.name, r.id);
562	      }
563	      done.push(label);
564	    }
565	  } catch (e: any) {
566	    const reason = String(e?.message ?? e).slice(0, 200);
567	    return {
568	      error:
569	        `Your DNS provider rejected part of this change (${reason}). ` +
570	        (done.length > 0
571	          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
572	          : "Nothing was changed and your existing records are untouched. ") +
573	        `Wait a minute and click Point at server again — it is safe to repeat.`,
574	    };
575	  }
576	  revalidatePath(`/dashboard/domains/${domainId}`);
577	  return {};
578	}
