562	// ---------- External-domain DNS setup + verification ----------
563	
564	/**
565	 * Return the DNS records a customer must publish at their registrar for an
566	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
567	 * ownership-verification record. Ownership-checked (caller must own the sub).
568	 *
569	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
570	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
571	 * note is returned so the panel still renders.
572	 */
573	export async function getEmailDnsRecords(
574	  subscriptionId: string,
575	): Promise<{
576	  error?: string;
577	  records?: DnsRecord[];
578	  verified?: boolean;
579	  external?: boolean;
580	  cloudflareConnected?: boolean;
581	}> {
582	  const user = await requireUser();
583	
584	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
585	  if (!sub) return { error: "Subscription not found." };
586	  if (sub.userId !== user.id) return { error: "Not your subscription." };
587	
588	  const domain = sub.domainName;
589	
590	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
591	  let dkimTxt = sub.dkimRecord ?? null;
592	  if (!dkimTxt && mailcowConfigured()) {
593	    try {
594	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
595	      if (!(await mcDomainExists(domain))) {
596	        await mcCreateDomain(domain).catch(() => {});
597	      }
598	      dkimTxt = await mcGetDkim(domain);
599	      if (dkimTxt) {
600	        await db.emailSubscription
601	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
602	          .catch(() => {});
603	      }
604	    } catch (e) {
605	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
606	    }
607	  }
608	
609	  const records: DnsRecord[] = [
610	    {
611	      type: "TXT",
612	      label: "Ownership verification",
613	      host: `_nxeon-verify.${domain}`,
614	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
615	      note: "Proves you control this domain. Required before mail is enabled.",
616	    },
617	    {
618	      type: "MX",
619	      label: "Mail routing (MX)",
620	      host: domain,
621	      value: MAIL_HOST,
622	      priority: MAIL_MX_PRIORITY,
623	    },
624	    {
625	      type: "TXT",
626	      label: "SPF",
627	      host: domain,
628	      value: SPF_VALUE,
629	      note: "Authorizes the Nxeon mail server to send for your domain.",
630	    },
631	    {
632	      type: "TXT",
633	      label: "DKIM",
634	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
635	      value: dkimTxt ?? "",
636	      note: dkimTxt
637	        ? undefined
638	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
639	    },
640	    {
641	      type: "TXT",
642	      label: "DMARC",
643	      host: `_dmarc.${domain}`,
644	      value: DMARC_VALUE,
645	      note: "Reporting policy for messages that fail SPF/DKIM.",
646	    },
647	  ];
648	
649	  return {
650	    records,
651	    verified: sub.verified,
652	    external: sub.external,
653	    // True for either connection shape (OAuth credentials or a legacy token).
654	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
655	  };
656	}
657	
658	/**
659	 * Verify that an EXTERNAL domain's owner has published our verification record.
660	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
661	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
662	 * corroboration. The result is derived entirely server-side from live DNS —
663	 * client input never decides the outcome. Rate-limited per user + subscription.
664	 */
665	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
666	  const user = await requireUser();
667	
668	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
669	  if (!sub) return { error: "Subscription not found." };
670	  if (sub.userId !== user.id) return { error: "Not your subscription." };
671	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
672	  if (sub.verified) return { ok: true };
673	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
674	
675	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
676	    max: 6,
677	    windowMs: 60_000,
678	  });
679	  if (!rl.ok) {
680	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
681	  }
682	
683	  const domain = sub.domainName;
684	  const expected = `nxeon-verify=${sub.verifyToken}`;
685	
686	  // Primary signal: the verification TXT record must contain our exact token.
687	  let tokenFound = false;
688	  try {
689	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
690	    // Each record may be split into multiple strings — join per-record chunks.
691	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
692	  } catch {
693	    tokenFound = false;
694	  }
695	
696	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
697	  let mxOk = false;
698	  try {
699	    const mx = await resolveMx(domain);
700	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
701	  } catch {
702	    mxOk = false;
703	  }
704	
705	  if (!tokenFound) {
706	    return {
707	      error: mxOk
708	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
709	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
710	    };
711	  }
712	
713	  await db.emailSubscription.update({
714	    where: { id: sub.id },
715	    data: { verified: true, verifiedAt: new Date() },
716	  });
717	
718	  await db.auditLog.create({
719	    data: {
720	      userId: user.id,
721	      action: "emailhosting.verify",
722	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
723	    },
724	  });
725	  revalidatePath("/dashboard/email");
726	  return { ok: true };
727	}
