969	  const [pending, start] = useTransition();
970	
971	  function run() {
972	    setError(null);
973	    start(async () => {
974	      const res = await checkEmailDeliverability(subscriptionId);
975	      if (res?.error) {
976	        setError(res.error);
977	        setReport(null);
978	      } else if (res?.report) {
979	        setReport(res.report);
980	      }
981	    });
982	  }
983	
984	  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
985	  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
986	  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;
987	
988	  return (
