1001	              <Badge tone="amber">
1002	                {warning} warning{warning === 1 ? "" : "s"}
1003	              </Badge>
1004	            ) : (
1005	              <Badge tone="green">All checks pass</Badge>
1006	            ))}
1007	        </div>
1008	        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
1009	          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
1010	        </button>
1011	      </div>
1012	
1013	      <p className="mt-2 text-xs text-slate-400">
1014	        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
1015	        and DMARC. If your mail is landing in spam, a failing row here is usually why.
1016	      </p>
1017	
1018	      {error && (
1019	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
1020	          {error}
1021	        </div>
1022	      )}
1023	
1024	      {report && (
1025	        <div className="mt-3 space-y-2">
1026	          {report.error && (
1027	            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
1028	              {report.error}
1029	            </div>
1030	          )}
1031	
1032	          {report.checks.map((c) => (
1033	            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
1034	              <div className="flex flex-wrap items-center gap-2">
1035	                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
1036	                <span className="text-sm font-medium text-slate-200">{c.label}</span>
1037	                <span className="text-[11px] text-slate-500">
1038	                  {c.type} · <span className="font-mono">{c.host}</span>
1039	                </span>
1040	              </div>
1041	
1042	              <div className="mt-2 grid gap-2 sm:grid-cols-2">
1043	                <div className="min-w-0">
1044	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
1045	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
1046	                    {c.observed || "— nothing published —"}
1047	                  </code>
1048	                </div>
1049	                <div className="min-w-0">
1050	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
1051	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
1052	                    {c.expected || "—"}
1053	                  </code>
1054	                </div>
1055	              </div>
1056	
1057	              <p
1058	                className={`mt-2 text-xs ${
1059	                  c.status === "fail"
1060	                    ? "text-red-400"
1061	                    : c.status === "warn"
1062	                      ? "text-amber-400"
1063	                      : c.status === "pass"
