95	      {hostingFromCents !== null && (
96	        <div className="card flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
97	          <div className="flex items-start gap-4">
98	            <span className="flex h-11 w-11 flex-none items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-300">
