/**
 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
 */

import { SANDBOX } from "./sandbox";
import { getSettingInt } from "./settings";

export function registrarConfigured(): boolean {
  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
}

/**
 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
 * exercised end to end without touching the registrar or a real domain.
 */
export function transfersAvailable(): boolean {
  return SANDBOX || registrarConfigured();
}

function baseUrl(): string {
  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
}

function authHeader(): string {
  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
  return "Basic " + Buffer.from(raw).toString("base64");
}

async function nc(
  method: string,
  path: string,
  body?: unknown,
  opts?: { nullOn404?: boolean }
): Promise<any> {
  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
  const res = await fetch(`${baseUrl()}${path}`, {
    method,
    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = {};
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    /* non-JSON error body */
  }
  if (!res.ok) {
    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
    // that has already dropped off the registrar's list) — let them opt in to a
    // null instead of an exception rather than string-matching an error message.
    if (opts?.nullOn404 && res.status === 404) return null;
    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
    throw new Error(`name.com: ${msg}`);
  }
  return json;
}

const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));

/** Fallback markup when no admin setting is saved. Matches the old hardcoded value. */
const DEFAULT_MARKUP_PCT = 25;

/**
 * Platform markup over the registrar's cost, as a percentage.
 *
 * MONEY BUG (fixed 2026-07-26): Settings → Domains writes `domain_markup_percent`
 * and displays it, but NOTHING read it — the only references were the stored
 * default, the save whitelist, and the admin input itself. Meanwhile this function
 * read `DOMAIN_MARKUP_PCT`, which is not set in `.env`, so every domain price
 * silently carried the hardcoded 25%. The panel therefore showed an operator **0%**
 * while customers were charged **25%**, and editing the field changed nothing.
 *
 * The admin setting is now the source of truth, with the env var as the fallback so
 * an operator who had set it keeps their behaviour. The stored default is corrected
 * from "0" to 25 so the panel states what is genuinely applied — displaying 0% while
 * charging 25% is precisely the class of untruth this codebase keeps producing.
 *
 * Safe to change now: zero domains have been sold and the setting had never been
 * saved, so no customer's price moves as a result of this fix.
 *
 * Async because it reads a setting. Callers resolve it ONCE and pass it into
 * `retailCents`, which stays pure so the arithmetic is trivially checkable.
 */
export async function domainMarkupPct(): Promise<number> {
  const envDefault = Number(process.env.DOMAIN_MARKUP_PCT ?? DEFAULT_MARKUP_PCT);
  const pct = await getSettingInt("domain_markup_percent", envDefault);
  // Clamp: a free-text admin field that multiplies every domain price. A stray
  // keystroke must not be able to bill a customer 5000% of cost.
  return Math.min(Math.max(Number.isFinite(pct) ? pct : envDefault, 0), 500);
}

/** Retail (customer) price for a registrar cost at `pct` markup. Pure. */
export function retailCents(costCents: number | null, pct: number): number | null {
  if (costCents === null) return null;
  return Math.round(costCents * (1 + pct / 100));
}

export type DomainCheck = {
  domain: string;
  available: boolean;
  premium: boolean;
  priceCents: number | null; // RETAIL — what the customer pays (per year)
  costCents: number | null; // registrar cost (per year)
  renewCents: number | null; // RETAIL renewal price
};

export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
  // Resolved ONCE for the whole batch: one settings read, and every price in a
  // single response is guaranteed to use the same markup.
  const pct = await domainMarkupPct();
  return (json.results ?? []).map((r: any) => {
    const cost = dollarsToCents(r.purchasePrice);
    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
    return {
      domain: r.domainName,
      available: r.purchasable === true,
      premium: r.premium === true,
      priceCents: retailCents(cost, pct),
      costCents: cost,
      renewCents: retailCents(renewCost, pct),
    };
  });
}

