import { useActionState, useState, useTransition } from "react";
import {
  renewDomainAction,
  toggleDomainAutoRenew,
  addDnsRecord,
  deleteDnsRecord,
  pointDomainAtServer,
} from "@/lib/actions-domains";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import { fmtMoney } from "@/components/ui/primitives";

export function DomainAutoRenewToggle({
  domainId,
  autoRenew,
}: {
  domainId: string;
  autoRenew: boolean;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        type="button"
        role="switch"
        aria-checked={autoRenew}
        aria-label="Auto-renew this domain"
        disabled={pending}
        onClick={() =>
          // Previously the returned/thrown result was DISCARDED, so a failed
          // toggle (e.g. Forbidden) was a silent no-op — the switch snapped back
          // on the next render with no explanation. Capture and surface it inline.
          start(async () => {
            setError(null);
            try {
              const res = (await toggleDomainAutoRenew(domainId)) as { error?: string } | void;
              if (res?.error) setError(res.error);
            } catch {
              setError("Couldn’t update auto-renew — try again.");
            }
          })
        }
        title={autoRenew ? "Auto-renew is on — click to turn off" : "Auto-renew is off — click to turn on"}
        className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400 disabled:opacity-50 ${
          autoRenew ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
        }`}
      >
        <span
          className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
            autoRenew ? "left-[18px]" : "left-0.5"
          }`}
        />
      </button>
    </span>
  );
}

