/**
 * Seed the BUNDLED, free "Domain Inbox" email plan that ships with every
 * domain registered through Nxeon (see lib/domain-inbox-email.ts and
 * purchaseDomain in lib/actions-domains.ts).
 *
 * This mirrors prisma/seed-hosting-email-plans.ts exactly, for the same reason:
 * it must be kept OUT of the paid Business Email storefront, belt-and-braces:
 *   - `active: false`  — every "browse/order a plan" query in the app filters
 *                        `where: { active: true }`, and orderEmailHosting()
 *                        rejects any plan that isn't active, so this can never
 *                        be *bought* (or self-served onto an EXISTING domain)
 *                        through the paid path.
 *   - `priceCents: 0`  — complimentary; no wallet charge is ever taken.
 *   - name "Free Domain Inbox" — the literal string lib/domain-inbox-email.ts's
 *     findDomainInboxPlan() looks up (kept deliberately distinct from the
 *     "…(bundled)" hosting-email names so the two families can never collide).
 *
 * Deliberately small — 1 mailbox, 2 GB — so it reads as a real free tier next to
 * the paid Starter (1 mailbox / 10 GB, see seed-email-plans.ts), not a clone of it.
 *
 * SCOPE: this plan is only ever attached going forward, by purchaseDomain, to a
 * domain at the moment it registers. It is never backfilled onto domains that
 * were already on the platform before this shipped — that is a deliberate,
 * separate decision the product owner has not made.
 *
 * Idempotent: dedupes by `name` and upserts. Safe to re-run.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-domain-inbox-plan.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

const NAME = "Free Domain Inbox";
const MAILBOXES = 1;
const STORAGE_GB = 2;
const SORT_ORDER = 89; // just ahead of the hosting-bundled plans (90/91/92)

async function main() {
  const data = {
    name: NAME,
    mailboxes: MAILBOXES,
    storageGB: STORAGE_GB,
    priceCents: 0, // complimentary — never charged
    termMonths: 1,
    active: false, // kept OUT of the paid Business Email storefront
    sortOrder: SORT_ORDER,
  };

  // No DB unique constraint on name — dedupe manually (matches seed-email-plans.ts).
  const existing = await db.emailPlan.findFirst({ where: { name: NAME } });
  if (existing) {
    await db.emailPlan.update({ where: { id: existing.id }, data });
    console.log(`  Updated: ${NAME} — ${MAILBOXES} mailbox · ${STORAGE_GB} GB · FREE (bundled, hidden)`);
  } else {
    await db.emailPlan.create({ data });
    console.log(`  Created: ${NAME} — ${MAILBOXES} mailbox · ${STORAGE_GB} GB · FREE (bundled, hidden)`);
  }

  const total = await db.emailPlan.count();
  console.log(`\nFree Domain Inbox plan seeded. Total EmailPlans in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

/**
 * The free "Domain Inbox" mailbox that ships with every domain registered
 * through Nxeon (owner decision, 2026-08-27 — see prisma/seed-domain-inbox-plan.ts).
 *
 * Deliberately NOT a "use server" module. Every export of a "use server" file is
 * automatically a public, directly-invokable Server Action — but
 * `setupDomainInboxEmail` below trusts its `userId`/`domainName` arguments
 * completely and does no ownership check of its own (exactly like
 * `orderEmailHostingCore` in lib/actions-email-hosting.ts, which stays
 * UNEXPORTED for the same reason). Its only intended caller is `purchaseDomain`
 * in lib/actions-domains.ts, AFTER that action's own auth + impersonation +
 * ownership checks have already run and the domain is confirmed ACTIVE for
 * that user. Exporting this from a "use server" module would let any signed-in
 * client call it directly with an arbitrary userId/domainName — the exact
 * cross-tenant mailbox shape the 2026-07-25 takeover fix exists to prevent (see
 * the SECURITY comments on orderEmailHostingCore / addMailbox). Keeping this
 * file plain, with no directive, makes it importable by other server modules
 * while staying impossible to reach from the client.
 *
 * Mirrors (deliberately, in miniature) lib/hosting-email.ts's setupHostingEmail
 * — a complimentary EmailSubscription minted for a domain the caller already
 * controls, on a plan kept out of the paid storefront. Where hosting-bundled
 * email is external+unverified until DNS is proven, a domain that was JUST
 * REGISTERED through Nxeon is already ours to route mail for, so this mirrors
 * orderEmailHostingCore's "in-account" branch instead: external:false,
 * verified immediately, no DNS step for the customer to complete.
 */

import { randomBytes } from "node:crypto";
import { db } from "./db";
import { encryptSecret } from "./crypto-box";
import { mailcowConfigured, mcCreateDomain, mcDomainExists, mcCreateMailbox } from "./mailcow";

/** Must match prisma/seed-domain-inbox-plan.ts's NAME exactly. */
const DOMAIN_INBOX_PLAN_NAME = "Free Domain Inbox";

// Same shape as lib/actions-email-hosting.ts's localPartRe — kept as a private
// copy rather than an import, since that file must not export anything a
// client could invoke as a Server Action (see file header above).
const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;

export type DomainInboxPlan = {
  id: string;
  name: string;
  mailboxes: number;
  storageGB: number;
};

/**
 * The bundled, free plan every Nxeon-registered domain's inbox is created on.
 * Read-only lookup — safe to call from Server Components (e.g. the domains
 * list / register wizard, to show the real mailbox/GB numbers) as well as from
 * `setupDomainInboxEmail` below.
 */
export async function findDomainInboxPlan(): Promise<DomainInboxPlan | null> {
  return db.emailPlan.findFirst({
    where: { name: DOMAIN_INBOX_PLAN_NAME, priceCents: 0, active: false },
    select: { id: true, name: true, mailboxes: true, storageGB: true },
  });
}

/**
 * Create the complimentary EmailSubscription — and, if the customer chose an
 * address during registration, the real mailbox — for a domain that was just
 * registered through Nxeon.
 *
 * Best-effort and NEVER throws: `purchaseDomain` has already charged the
 * customer and registered the domain at the regististrar by the time this
 * runs, so a missing plan seed or a Mailcow hiccup here must never surface as
 * a registration failure. A skipped/failed mailbox just leaves the
 * subscription in place with zero mailboxes — addable later from
 * /dashboard/email, same as any other subscription.
 *
 * NOT retroactive: this is only ever called at the moment of a NEW
 * registration. Domains already on the platform before this shipped are
 * never backfilled (a separate, larger cost decision the owner hasn't made).
 */
export async function setupDomainInboxEmail(params: {
  userId: string;
  domainName: string;
  expiresAt: Date | null;
  /** Local-part the customer chose during registration, if any (e.g. "hello"). */
  mailboxLocalPart?: string | null;
}): Promise<void> {
  const { userId, domainName, expiresAt } = params;
  try {
    // Global dedup — one subscription per domain across ALL accounts, the same
    // guard every other EmailSubscription creator uses (2026-07-25 fix). A
    // fresh registration should never collide, but never double-grant either.
    const dupe = await db.emailSubscription.findFirst({
      where: { domainName, status: { not: "CANCELLED" } },
    });
    if (dupe) return;

    const plan = await findDomainInboxPlan();
    if (!plan) {
      console.warn(`[domain-inbox-email] "${DOMAIN_INBOX_PLAN_NAME}" plan not seeded — skipping ${domainName}`);
      return;
    }

    const sub = await db.emailSubscription.create({
      data: {
        userId,
        domainName,
        emailPlanId: plan.id,
        status: "ACTIVE",
        autoRenew: true,
        termMonths: 1,
        expiresAt,
        // In-account domain — we just registered it, so we control its DNS.
        // Treat as verified immediately, mirroring orderEmailHostingCore's
        // in-account branch (no DNS step for the customer to complete).
        external: false,
        verified: true,
        verifiedAt: new Date(),
        verifyToken: null,
      },
    });

    await db.auditLog
      .create({
        data: {
          userId,
          action: "domain.freeinbox.setup",
          detail: `${domainName} · ${plan.name} (${plan.mailboxes} mailbox, ${plan.storageGB} GB)`,
        },
      })
      .catch(() => {});

    const local = String(params.mailboxLocalPart ?? "")
      .trim()
      .toLowerCase();
    // No address chosen — reserved but mailbox-less, same "add it later" state
    // orderEmailHostingCore leaves every fresh subscription in.
    if (!local) return;
    // A malformed choice is skipped rather than failing the domain purchase —
    // the paid transaction already succeeded and must not be undone by a
    // cosmetic mailbox-name typo. The customer can add a valid one later.
    if (!localPartRe.test(local) || local.length > 64) {
      console.warn(`[domain-inbox-email] invalid local-part "${local}" for ${domainName} — left mailbox-less`);
      return;
    }

    const address = `${local}@${domainName}`;
    // Mailbox.address is GLOBALLY unique (2026-07-25 fix) — a collision here
    // just means someone else already holds that exact address; leave this
    // subscription mailbox-less rather than fail the registration.
    const existingMailbox = await db.mailbox.findUnique({ where: { address } });
    if (existingMailbox) {
      console.warn(`[domain-inbox-email] ${address} already exists — left ${domainName}'s inbox mailbox-less`);
      return;
    }

    const quotaMB = plan.storageGB * 1024;
    const mailbox = await db.mailbox.create({
      data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
    });

    if (!mailcowConfigured()) return; // left PROVISIONING, same as addMailbox()

    try {
      if (!(await mcDomainExists(domainName))) {
        await mcCreateDomain(domainName).catch(() => {});
      }
      const password = randomBytes(18).toString("base64url");
      await mcCreateMailbox({ localPart: local, domain: domainName, name: address, password, quotaMB });
      await db.mailbox.update({
        where: { id: mailbox.id },
        data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
      });
    } catch (e) {
      await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "FAILED" } }).catch(() => {});
      console.warn(`[domain-inbox-email] provisioning ${address} failed:`, e);
    }
  } catch (e) {
    console.warn(`[domain-inbox-email] setup for ${domainName} failed:`, e);
  }
}

