import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { registrarConfigured, transfersAvailable, getDnsHosts } from "@/lib/registrar";
import { StatCard, Badge, StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { DomainSearch } from "@/components/customer/DomainSearch";
import { DomainAutoRenewToggle } from "@/components/customer/DomainControls";
import { findDomainInboxPlan } from "@/lib/domain-inbox-email";

export const dynamic = "force-dynamic";

function daysUntil(d: Date): number {
  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
}

function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
  if (days === null) return "slate";
  if (days < 0) return "red";
  if (days <= 30) return "amber";
  return "green";
}

function expiryLabel(d: Date | null): string {
  if (!d) return "—";
  const days = daysUntil(d);
  if (days < 0) return `expired ${-days}d ago`;
  if (days === 0) return "expires today";
  return `in ${days} day${days === 1 ? "" : "s"}`;
}

const statusDotFor = (s: string) =>
  s === "ACTIVE"
    ? "RUNNING"
    : s === "PENDING" || s === "TRANSFER_PENDING"
      ? "PENDING"
      : s === "EXPIRED"
        ? "SUSPENDED"
        : "ERROR";

/** Email Inbox cell — real per-domain state, never a marketing placeholder.
 *  `sub` is this domain's EmailSubscription (created automatically for every
 *  NEW registration since the free-inbox feature shipped — see
 *  lib/domain-inbox-email.ts). Domains registered before that, or where the
 *  customer skipped naming a mailbox, show a real "Set up" CTA instead. */
function EmailInboxCell({
  sub,
  compact,
}: {
  sub: { activeMailboxes: number; totalMailboxes: number } | null;
  compact?: boolean;
}) {
  if (!sub) {
    return (
      <Link
        href="/dashboard/email"
        className={compact ? "text-xs font-medium text-brand-300 hover:text-brand-200" : "btn-secondary px-3 py-1 text-xs"}
      >
        Set up →
      </Link>
    );
  }
  if (sub.totalMailboxes === 0) {
    return (
      <span className="flex items-center gap-2">
        <Badge tone="amber">No mailbox yet</Badge>
        <Link href="/dashboard/email" className="text-xs font-medium text-brand-300 hover:text-brand-200">
          Set up →
        </Link>
      </span>
    );
  }
  return (
    <Badge tone={sub.activeMailboxes > 0 ? "green" : "slate"}>
      {sub.activeMailboxes > 0
        ? `Active · ${sub.activeMailboxes} mailbox${sub.activeMailboxes === 1 ? "" : "es"}`
        : "Provisioning"}
    </Badge>
  );
}

function nameserversLabel(ns: string[]): string {
  if (ns.length === 0) return "Default (name.com)";
  const shown = ns.slice(0, 2).join(", ");
  return ns.length > 2 ? `${shown} +${ns.length - 2}` : shown;
}

export default async function DomainsPage() {
  const user = await requireUser();
  const configured = registrarConfigured();
  const canTransfer = transfersAvailable();
  const domains = await db.domain.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });

  // DNS record counts for active domains (best-effort — registrar may be briefly unavailable).
  const recordCounts = new Map<string, number | null>();
  if (configured) {
    await Promise.all(
      domains
        .filter((d) => d.status === "ACTIVE")
        .map(async (d) => {
          try {
            const hosts = await getDnsHosts(d.name);
            recordCounts.set(d.id, hosts.length);
          } catch {
            recordCounts.set(d.id, null);
          }
        })
    );
  }

  // Real per-domain free-inbox state (Part 2). Only domains registered since
  // the feature shipped have a row here — nothing is backfilled onto older
  // domains, so a "Set up" CTA for those is accurate, not a bug.
  const emailSubs = domains.length
    ? await db.emailSubscription.findMany({
        where: { userId: user.id, domainName: { in: domains.map((d) => d.name) }, status: { not: "CANCELLED" } },
        select: { domainName: true, mailboxes: { select: { status: true } } },
      })
    : [];
  const subByDomain = new Map(
    emailSubs.map((s) => [
      s.domainName,
      {
        totalMailboxes: s.mailboxes.length,
        activeMailboxes: s.mailboxes.filter((m) => m.status === "ACTIVE").length,
      },
    ])
  );

  // Real numbers for the cross-sell banner — never a guessed figure.
  const inboxPlan = await findDomainInboxPlan();

  const active = domains.filter((d) => d.status === "ACTIVE").length;
  const expiringSoon = domains.filter(
    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) <= 30 && daysUntil(d.expiresAt) >= 0
  ).length;
  const expiringToday = domains.filter(
    (d) => d.status === "ACTIVE" && d.expiresAt && daysUntil(d.expiresAt) === 0
  ).length;
  const autoRenewOn = domains.filter((d) => d.autoRenew).length;

  // Quick Actions in the sidebar need a concrete domain to manage — the most
  // recently registered one (list is already ordered createdAt desc).
  const primaryDomain = domains.find((d) => d.status === "ACTIVE") ?? domains[0] ?? null;

  return (
    <div className="space-y-6">
      <PortalHero variant="domains" title="Domains" sub="Register, transfer in and manage domains, right next to your servers.">
        {canTransfer && (
          <Link href="/dashboard/domains/transfer" className="btn-secondary">
            Transfer a domain in
          </Link>
        )}
        {configured && (
          <Link href="/dashboard/domains/ideas" className="btn-secondary">
            Find a name
          </Link>
        )}
        {configured && (
          <Link href="/dashboard/domains/register" className="btn-primary">
            Register a domain
          </Link>
        )}
      </PortalHero>

      {domains.length > 0 && (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          <StatCard
            label="Total domains"
            value={String(domains.length)}
            icon={
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                <circle cx="12" cy="12" r="9" />
                <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
              </svg>
            }
          />
          <StatCard
            label="Expiring soon"
            value={String(expiringSoon)}
            delta={expiringSoon === 0 ? "nothing due" : "within 30 days"}
            deltaGood={expiringSoon === 0}
            icon={
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                <circle cx="12" cy="12" r="9" />
                <path d="M12 7v5l3.5 2" />
              </svg>
            }
          />
          <StatCard
            label="Expiring today"
            value={String(expiringToday)}
            delta={expiringToday === 0 ? "nothing today" : "renew now"}
            deltaGood={expiringToday === 0}
            icon={
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                <path d="M12 9v4M12 16.5h.01" />
                <path d="M10.3 3.9 2.7 17.1a1.6 1.6 0 0 0 1.4 2.4h15.8a1.6 1.6 0 0 0 1.4-2.4L13.7 3.9a1.6 1.6 0 0 0-2.8 0Z" />
              </svg>
            }
          />
          <StatCard
            label="Auto renew on"
            value={String(autoRenewOn)}
            delta={autoRenewOn === domains.length ? "all covered" : `${domains.length - autoRenewOn} off`}
            deltaGood={autoRenewOn === domains.length}
            icon={
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                <path d="M3 12a9 9 0 0 1 15.4-6.4L21 8M21 3v5h-5" />
                <path d="M21 12a9 9 0 0 1-15.4 6.4L3 16M3 21v-5h5" />
              </svg>
            }
          />
        </div>
      )}

      {/* Cross-sell banner — the claim is real: every domain registered from
          here on gets a genuine EmailSubscription + reserved mailbox slot,
          not just a marketing line (see lib/domain-inbox-email.ts). */}
      <div className="card relative overflow-hidden border-emerald-500/20 bg-gradient-to-br from-emerald-500/[0.07] to-transparent p-5 sm:p-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-start gap-4">
            <span className="flex h-11 w-11 flex-none items-center justify-center rounded-xl border border-emerald-500/20 bg-emerald-500/10 text-emerald-300">
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                <rect x="3" y="5" width="18" height="14" rx="2" />
                <path d="m3.5 7 8.5 6 8.5-6" />
              </svg>
            </span>
            <div>
              <h2 className="font-semibold text-white">Every new domain comes with a free Business Email inbox</h2>
              <p className="mt-1 max-w-xl text-sm text-slate-400">
                Register a domain and set up you@yourdomain in the same flow —{" "}
                {inboxPlan ? `${inboxPlan.mailboxes} mailbox, ${inboxPlan.storageGB} GB, ` : ""}
                free for as long as the domain is active. Already have a domain here? Add its inbox any
                time from Email.
              </p>
            </div>
          </div>
          <Link href="/dashboard/email" className="btn-secondary shrink-0 self-start sm:self-center">
            Learn more →
          </Link>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-[1fr_340px]">
        <div className="space-y-6">
          <DomainSearch configured={configured} />

          {domains.length === 0 ? (
            <EmptyState
              title="No domains yet"
              sub={
                configured
                  ? "Search above for an exact name, or let the generator turn a description of your business into available ones — then register and point it at any of your servers in minutes."
                  : "Domain registration lights up once the registrar integration is configured. Your registered domains will appear here."
              }
              action={
                configured || canTransfer ? (
                  <div className="flex flex-wrap items-center justify-center gap-3">
                    {configured && (
                      <Link href="/dashboard/domains/register" className="btn-primary">
                        Register your first domain
                      </Link>
                    )}
                    {configured && (
                      <Link href="/dashboard/domains/ideas" className="btn-secondary">
                        Not sure what to call it? Generate names
                      </Link>
                    )}
                    {canTransfer && (
                      <Link href="/dashboard/domains/transfer" className="btn-secondary">
                        Already own one? Transfer it in
                      </Link>
                    )}
                  </div>
                ) : undefined
              }
            />
          ) : (
            <div className="card p-0">
              <div className="flex items-center justify-between px-5 pt-5">
                <p className="section-label">Your domains</p>
                <span className="text-xs text-slate-500">{domains.length} total</span>
              </div>

              {/* Card grid on small screens, table on large */}
              <div className="grid gap-3 p-5 lg:hidden">
                {domains.map((d) => {
                  const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
                  const count = recordCounts.get(d.id);
                  const sub = subByDomain.get(d.name) ?? null;
                  return (
                    <Link
                      key={d.id}
                      href={`/dashboard/domains/${d.id}`}
                      className="card card-hover block p-4"
                    >
                      <div className="flex items-center justify-between gap-2">
                        {/* min-w-0 so `truncate` can actually shrink a long domain
                            name at 390px instead of pushing the status dot off-card. */}
                        <span className="min-w-0 truncate font-mono text-sm font-semibold text-slate-100">{d.name}</span>
                        <StatusDot status={statusDotFor(d.status)} label={d.status} />
                      </div>
                      {d.status === "TRANSFER_PENDING" && (
                        <p className="mt-2 text-xs text-amber-300">
                          Transfer in progress — approve the confirmation email from your old registrar. Usually
                          5–7 days.
                        </p>
                      )}
                      {d.status === "TRANSFER_FAILED" && (
                        <p className="mt-2 text-xs text-red-300">
                          Transfer didn&apos;t complete — you were credited back. Tap to see why.
                        </p>
                      )}
                      <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
                        {d.status === "TRANSFER_PENDING" ? (
                          <Badge tone="amber">transfer in</Badge>
                        ) : (
                          <Badge tone={expiryTone(days)}>{expiryLabel(d.expiresAt)}</Badge>
                        )}
                        <Badge tone={d.autoRenew ? "green" : "slate"}>
                          auto-renew {d.autoRenew ? "on" : "off"}
                        </Badge>
                        {d.status === "ACTIVE" && (
                          <Badge tone="slate">{count === null || count === undefined ? "DNS —" : `${count} DNS`}</Badge>
                        )}
                        <span className="ml-auto text-slate-400">{fmtMoney(d.priceCents)}/yr</span>
                      </div>
                      <div className="mt-2 flex items-center justify-between gap-2 border-t border-white/[0.05] pt-2 text-xs">
                        <span className="text-slate-500">Email inbox</span>
                        <EmailInboxCell sub={sub} compact />
                      </div>
                      <div className="mt-1 flex items-center justify-between gap-2 text-xs">
                        <span className="text-slate-500">Nameservers</span>
                        <span className="truncate font-mono text-slate-400">{nameserversLabel(d.nameservers)}</span>
                      </div>
                    </Link>
                  );
                })}
              </div>

              <div className="hidden overflow-x-auto lg:block">
                <table className="table-shell mt-2 min-w-[980px]">
                  <thead>
                    <tr>
                      <th>Domain</th>
                      <th>Status</th>
                      <th>Expires</th>
                      <th>DNS</th>
                      <th>Nameservers</th>
                      <th>Email Inbox</th>
                      <th>Price</th>
                      <th>Auto-renew</th>
                      <th className="text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {domains.map((d) => {
                      const days = d.expiresAt ? daysUntil(d.expiresAt) : null;
                      const count = recordCounts.get(d.id);
                      const sub = subByDomain.get(d.name) ?? null;
                      return (
                        <tr key={d.id}>
                          <td>
                            <Link
                              href={`/dashboard/domains/${d.id}`}
                              className="font-mono text-sm font-semibold text-slate-100 hover:text-brand-300"
                            >
                              {d.name}
                            </Link>
                          </td>
                          <td>
                            <StatusDot status={statusDotFor(d.status)} label={d.status} />
                          </td>
                          <td>
                            {d.status === "TRANSFER_PENDING" ? (
                              <div className="flex flex-col">
                                <span className="text-sm text-amber-300">transferring in</span>
                                <span className="text-xs text-slate-500">approve the registrar email · 5–7 days</span>
                              </div>
                            ) : d.expiresAt ? (
                              <div className="flex flex-col">
                                <span className="text-sm text-slate-300">
                                  {d.expiresAt.toISOString().slice(0, 10)}
                                </span>
                                <span className={`text-xs ${expiryTone(days) === "amber" ? "text-amber-400" : expiryTone(days) === "red" ? "text-red-400" : "text-slate-500"}`}>
                                  {expiryLabel(d.expiresAt)}
                                </span>
                              </div>
                            ) : (
                              <span className="text-slate-500">—</span>
                            )}
                          </td>
                          <td className="text-slate-400">
                            {d.status !== "ACTIVE"
                              ? "—"
                              : count === null || count === undefined
                                ? "—"
                                : `${count} record${count === 1 ? "" : "s"}`}
                          </td>
                          <td className="max-w-[180px] truncate font-mono text-xs text-slate-400">
                            {nameserversLabel(d.nameservers)}
                          </td>
                          <td>
                            <EmailInboxCell sub={sub} />
                          </td>
                          <td className="text-slate-400">{fmtMoney(d.priceCents)}/yr</td>
                          <td>
                            <DomainAutoRenewToggle domainId={d.id} autoRenew={d.autoRenew} />
                          </td>
                          <td className="text-right">
                            <Link href={`/dashboard/domains/${d.id}`} className="btn-secondary px-3 py-1 text-xs">
                              Manage
                            </Link>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Sidebar — persistent CTAs + shortcuts, same two-column shape
            DomainRegisterWizard already uses (grid-cols-[1fr_320px]) for its
            own order-summary aside. */}
        <aside className="space-y-4">
          {configured && (
            <div className="card">
              <p className="section-label mb-2">Register a new domain</p>
              <p className="mb-3 text-sm text-slate-400">
                Search a name, pick a term, and it&apos;s live in minutes — with a free inbox included.
              </p>
              <Link href="/dashboard/domains/register" className="btn-primary w-full justify-center">
                Register a domain
              </Link>
            </div>
          )}

          {canTransfer && (
