import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";
import fs from "node:fs";

const BASE = "https://staging.nxeon.cloud";
const SHOT_DIR = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/shots";
fs.mkdirSync(SHOT_DIR, { recursive: true });

const RUN_ID = Date.now().toString(36);
const BASE_NAME = `nxaudit${RUN_ID}`;
const MAILBOX_LOCAL = "hello";

let RESULT = { domain: null, mailboxAddress: `${MAILBOX_LOCAL}@` };

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ bypassCSP: true });
  const page = await context.newPage();
  page.setDefaultTimeout(30000);

  console.log("== Login ==");
  await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
  await page.fill('input[name="email"], input[type="email"]', "claude-audit-2026@nxeon.test");
  await page.fill('input[name="password"], input[type="password"]', "AuditPass123!");
  await Promise.all([
    page.waitForNavigation({ waitUntil: "domcontentloaded" }).catch(() => {}),
    page.click('button[type="submit"]'),
  ]);
  await page.waitForTimeout(1500);
  console.log("post-login url:", page.url());

  console.log("== Go to register wizard ==");
  await page.goto(`${BASE}/dashboard/domains/register`, { waitUntil: "domcontentloaded" });
  await page.waitForTimeout(1000);

  console.log("== Search for a domain name ==");
  const searchInput = page.locator('input[placeholder="another-name.com"]');
  await searchInput.fill(BASE_NAME);
  await page.waitForTimeout(1200);

  // Prefer an available, non-premium .com result; fall back to first available.
  const rows = page.locator("ul li", { hasText: "Choose" });
  const count = await rows.count();
  console.log(`search returned ${count} choosable rows`);
  if (count === 0) {
    throw new Error("No available domain found for search term " + BASE_NAME);
  }
  let chosenRow = rows.first();
  for (let i = 0; i < count; i++) {
    const text = await rows.nth(i).innerText();
    if (text.includes(".com")) {
      chosenRow = rows.nth(i);
      break;
    }
  }
  const chosenText = await chosenRow.innerText();
  console.log("chosen row text:", chosenText.replace(/\s+/g, " "));
  await chosenRow.getByRole("button", { name: "Choose" }).click();
  await page.waitForTimeout(500);

  // Read the confirmed domain from the top confirm box (font-mono span).
  const domainSpan = page.locator("span.font-mono.text-base.font-semibold").first();
  RESULT.domain = (await domainSpan.innerText()).trim();
  RESULT.mailboxAddress = `${MAILBOX_LOCAL}@${RESULT.domain}`;
  console.log("Domain chosen:", RESULT.domain);

  console.log("== Step: Domain -> Continue ==");
  await page.getByRole("button", { name: /Continue/ }).click();
  await page.waitForTimeout(500);

  console.log("== Step: Term -> Continue (default 1yr) ==");
  await page.getByRole("button", { name: /Continue/ }).click();
  await page.waitForTimeout(500);

  console.log("== Step: Contact ==");
  await page.fill('label:has-text("First name") + input, input', ""); // no-op guard
  async function fillLabeled(labelText, value) {
    const input = page.locator(`label:has-text("${labelText}")`).locator("xpath=following-sibling::input[1]");
    await input.fill(value);
  }
  await fillLabeled("First name", "Claude");
  await fillLabeled("Last name", "Audit");
  await fillLabeled("Street address", "123 Test St");
  await fillLabeled("City", "Testville");
  await fillLabeled("State / Province", "CA");
  await fillLabeled("Postal code", "90001");
  await fillLabeled("Phone", "+1.5551234567");
  // Email field is prefilled with the account's own email — leave as is.
  await page.waitForTimeout(300);
  await page.getByRole("button", { name: /Continue/ }).click();
  await page.waitForTimeout(500);

  console.log("== Step: Email (free inbox) ==");
  const emailStepHeading = page.getByRole("heading", { name: "Set up your free inbox" });
  const hasEmailStep = await emailStepHeading.count();
  console.log("Email step present:", hasEmailStep > 0);
  if (hasEmailStep > 0) {
    await page.fill('input[placeholder="hello"]', MAILBOX_LOCAL);
    await page.waitForTimeout(400);
    await page.screenshot({ path: `${SHOT_DIR}/1-wizard-email-step.png`, fullPage: true });
    await page.getByRole("button", { name: /Continue/ }).click();
    await page.waitForTimeout(500);
  } else {
    console.log("WARNING: Email step did not render — screenshotting current step instead.");
    await page.screenshot({ path: `${SHOT_DIR}/1-wizard-email-step-MISSING.png`, fullPage: true });
  }

  console.log("== Step: Review ==");
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${SHOT_DIR}/2-wizard-review.png`, fullPage: true });
  const registerBtn = page.getByRole("button", { name: /^Register —/ });
  await registerBtn.click();

  console.log("== Waiting for redirect to domain detail page ==");
  await page.waitForURL(/\/dashboard\/domains\/[a-z0-9]+\?new=1/, { timeout: 30000 }).catch((e) => {
    console.log("did not see expected redirect URL, current url:", page.url());
  });
  await page.waitForTimeout(1500);
  console.log("post-register url:", page.url());
  await page.screenshot({ path: `${SHOT_DIR}/3-domain-detail-after-register.png`, fullPage: true });

  console.log("== Go to redesigned Domains list page ==");
  await page.goto(`${BASE}/dashboard/domains`, { waitUntil: "domcontentloaded" });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${SHOT_DIR}/4-domains-list-redesign.png`, fullPage: true });

  await browser.close();

  fs.writeFileSync(
    "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/verify-result.json",
    JSON.stringify(RESULT, null, 2)
  );
  console.log("== DONE ==");
  console.log(RESULT);
})().catch((e) => {
  console.error("VERIFY FAILED:", e);
  process.exit(1);
});

